<div class="page-title"><div><h2>فروش‌ها</h2><p class="text-muted">تخصیص فروشنده روی فروش ثبت می‌شود و تاریخچه‌ی تغییر آن حفظ می‌گردد.</p></div></div><section class="card"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>قرارداد</th><th>مشتری</th><th>فروشنده</th><th>مبلغ تامین‌شده</th><th>کانال</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach (($sales ?? []) as $sale): ?><tr><td><?= e($sale['contract_number']) ?></td><td><?= e($sale['customer_name']) ?></td><td><?= e($sale['seller_name'] ?: 'نیازمند تخصیص') ?></td><td><?= money_toman($sale['financed_amount']) ?></td><td><?= e($sale['sales_channel']) ?></td><td><?= e($sale['status']) ?></td><td><form method="post" action="<?= e(url('plugin/accounting/sales/assign')) ?>" class="d-flex gap-1 align-items-center"><?= csrf_field() ?><input type="hidden" name="sale_id" value="<?= (int) $sale['id'] ?>"><select name="seller_user_id" required><option value="">فروشنده</option><?php foreach (($staff ?? []) as $person): ?><option value="<?= (int) $person['id'] ?>"<?= (int) ($sale['seller_user_id'] ?? 0) === (int) $person['id'] ? ' selected' : '' ?>><?= e($person['full_name']) ?> (<?= e(role_label($person['role'])) ?>)</option><?php endforeach; ?></select><button class="btn btn-sm btn-primary" type="submit">ثبت</button></form></td></tr><?php endforeach; ?><?php if (empty($sales)): ?><tr><td colspan="7" class="empty">فروشی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div><?= render_pagination($pagination ?? [], static function ($page) { return url('plugin/accounting/sales', ['page' => $page]); }) ?></section>
